CREATE TABLE escalation_connections(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),provider TEXT NOT NULL CHECK(provider IN ('github','linear','jira','slack')),target TEXT NOT NULL,base_url TEXT,token_cipher TEXT,webhook_cipher TEXT,updated_at INTEGER NOT NULL,UNIQUE(project_id,provider));
CREATE TABLE escalation_issues(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),connection_id TEXT NOT NULL REFERENCES escalation_connections(id),provider TEXT NOT NULL,provider_id TEXT NOT NULL,issue_key TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL,assignee TEXT,closed INTEGER NOT NULL,provider_updated_at INTEGER NOT NULL,UNIQUE(connection_id,provider_id));
CREATE TABLE escalation_links(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),issue_id TEXT NOT NULL REFERENCES escalation_issues(id),dependency TEXT NOT NULL DEFAULT '',recovery TEXT NOT NULL DEFAULT 'unconfirmed' CHECK(recovery IN ('unconfirmed','observed')),observation TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,UNIQUE(conversation_id,issue_id));
CREATE INDEX escalation_links_issue ON escalation_links(issue_id);
CREATE TABLE escalation_operations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),provider TEXT NOT NULL,intent_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('sending','complete','uncertain','failed')),remote_url TEXT,created_at INTEGER NOT NULL);
CREATE TABLE escalation_handoffs(id TEXT PRIMARY KEY REFERENCES escalation_operations(id),project_id TEXT NOT NULL REFERENCES projects(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),channel TEXT NOT NULL,url TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE escalation_attachment_grants(token_hash TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL,media_id TEXT NOT NULL REFERENCES media(id),operation_id TEXT NOT NULL REFERENCES escalation_operations(id),expires_at INTEGER NOT NULL);
CREATE TABLE escalation_deliveries(connection_id TEXT NOT NULL REFERENCES escalation_connections(id),delivery_id TEXT NOT NULL,issue_id TEXT NOT NULL REFERENCES escalation_issues(id),provider_updated_at INTEGER NOT NULL,received_at INTEGER NOT NULL,PRIMARY KEY(connection_id,delivery_id));
CREATE TABLE escalation_drafts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),issue_id TEXT NOT NULL REFERENCES escalation_issues(id),provider_updated_at INTEGER NOT NULL,content TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','approved','sent','cancelled')),approved_by TEXT,approved_at INTEGER,message_id TEXT REFERENCES messages(id),created_at INTEGER NOT NULL,UNIQUE(issue_id,conversation_id,provider_updated_at));
